import { and, eq, lte, or } from \"drizzle-orm\";
import { newId } from \"@/lib/id\";
import { OwnershipHandoverError } from \"@/lib/errors\";
import { getDb, members, organizations, ownershipHandovers } from \"@/server/db\";
import { toIsoTimestamp } from \"@/types/common\";
import type { OrgId, UserId, IsoTimestamp, MemberId } from \"@/types/common\";
import type { Role } from \"@/types/member\";
import type { OwnershipHandover } from \"@/types/organization\";

function map(row: typeof ownershipHandovers."'$inferSelect): OwnershipHandover {
  return { ...row, orgId: row.orgId as OrgId, fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId, createdAt: row.createdAt as IsoTimestamp,
    expiresAt: row.expiresAt as IsoTimestamp, resolvedAt: row.resolvedAt as IsoTimestamp | null };
}

export function pending(orgId: OrgId): OwnershipHandover | null {
  const row = getDb().select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
  return row ? map(row) : null;
}

export function create(orgId: OrgId, fromUserId: UserId, toUserId: UserId): OwnershipHandover {
  const db = getDb();
  return db.transaction((tx) => {
    const now = toIsoTimestamp(new Date());
    tx.update(ownershipHandovers).set({ status: "expired", resolvedAt: now }).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"), lte(ownershipHandovers.expiresAt, now))).run();
    const open = tx.select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
    if (open) throw new OwnershipHandoverError("pending_exists");
    return map(tx.insert(ownershipHandovers).values({ id: newId(), orgId, fromUserId, toUserId, status: "pending", createdAt: now, expiresAt: toIsoTimestamp(new Date(new Date(now).getTime() + 7 * 86400000)), resolvedAt: null }).returning().get());
  });
}

export function resolve(orgId: OrgId, actorId: UserId, status: "accepted" | "declined" | "canceled") {
  const db = getDb();
  return db.transaction((tx) => {
    const row = tx.select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
    if (!row || (status === "canceled" ? row.fromUserId !== actorId : row.toUserId !== actorId)) throw new OwnershipHandoverError("nothing_pending");
    const now = toIsoTimestamp(new Date());
    if (row.expiresAt <= now) throw new OwnershipHandoverError(status === "canceled" ? "nothing_pending" : "expired");
    const changes: { memberId: MemberId; from: Role; to: Role }[] = [];
    if (status === "accepted") {
      const target = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, row.toUserId))).get();
      const previous = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, row.fromUserId))).get();
      if (!target || target.archivedAt || target.status !== "active" || !previous || previous.archivedAt || previous.status !== "active") throw new OwnershipHandoverError("nothing_pending");
      if (target.role !== "owner") {
        tx.update(members).set({ role: "owner", updatedAt: now }).where(eq(members.id, target.id)).run();
        changes.push({ memberId: target.id as MemberId, from: target.role, to: "owner" });
      }
      tx.update(organizations).set({ ownerId: row.toUserId, updatedAt: now }).where(eq(organizations.id, orgId)).run();
      if (previous.role === "owner") {
        tx.update(members).set({ role: "admin", updatedAt: now }).where(eq(members.id, previous.id)).run();
        changes.push({ memberId: previous.id as MemberId, from: "owner", to: "admin" });
      }
    }
    const updated = tx.update(ownershipHandovers).set({ status, resolvedAt: now }).where(eq(ownershipHandovers.id, row.id)).returning().get();
    return { offer: map(updated), changes };
  });
}

export function cancelForMember(orgId: OrgId, userId: UserId): void {
  const now = toIsoTimestamp(new Date());
  getDb().update(ownershipHandovers).set({ status: "canceled", resolvedAt: now }).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"), or(eq(ownershipHandovers.fromUserId, userId), eq(ownershipHandovers.toUserId, userId)))).run();
}
