async function requireRecordedOwner(actor: Actor, orgId: OrgId): Promise<Organization> {
  const org = requireFound(await orgRepo.findOrgById(orgId), \"Organization\", orgId);
  if (org.ownerId "'!== actor.userId) {
    throw new PermissionDeniedError("org:update", { action: "org:update", resourceKind: "organization", allowed: false, reason: "denied_by_role" });
  }
  return org;
}

export async function initiateOwnershipHandover(actor: Actor, orgId: OrgId, toUserId: UserId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await requireRecordedOwner(actor, orgId);
  if (toUserId === actor.userId) throw new OwnershipHandoverError("self");
  const member = await memberRepo.findMember(orgId, toUserId);
  if (!member || member.status !== "active") throw new NotFoundError("Member", toUserId);
  const offer = handoverRepo.create(orgId, actor.userId, toUserId);
  await notify(orgId, "ownership_handover", [toUserId], { title: "Workspace ownership offered", body: "You have been invited to accept workspace ownership.", href: "/settings/organization", actorId: actor.userId });
  return offer;
}

export async function getPendingOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  const offer = handoverRepo.pending(orgId);
  return offer && offer.expiresAt > toIsoTimestamp(new Date()) ? offer : null;
}

export async function acceptOwnershipHandover(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const { offer, changes } = handoverRepo.resolve(orgId, actor.userId, "accepted");
  for (const change of changes) await emit("member.role_changed", { ...actorEnvelope(actor), ...change });
  await emit("organization.ownership_transferred", { ...actorEnvelope(actor), fromUserId: offer.fromUserId, toUserId: offer.toUserId });
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

export async function declineOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  return handoverRepo.resolve(orgId, actor.userId, "declined").offer;
}

export async function cancelOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await requireRecordedOwner(actor, orgId);
  return handoverRepo.resolve(orgId, actor.userId, "canceled").offer;
}
