from pathlib import Path
p=Path('src/server/repositories/member-repository.ts'); s=p.read_text().replace('and, count, desc, eq, isNull, like, or','and, count, desc, eq, gt, isNull, like, or').replace('getDb, members, users','getDb, members, users, ownershipHandovers'); start=s.index('  const row = getDb()\\n    .update(members)',s.index('export async function archiveMember')); end=s.index('\\n\\n  if ("'!row)'"',start); s=s[:start]+'''  const db = getDb();
  const row = db.transaction((tx) => {
    const now = toIsoTimestamp(new Date());
    const removed = tx.update(members)
      .set({ ...archivePatch(), status: \"suspended\" })
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
      .returning().get();
    if (removed) {
      tx.update(ownershipHandovers).set({ status: \"canceled\", resolvedAt: now })
        .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, \"pending\"),
          gt(ownershipHandovers.expiresAt, now),
          or(eq(ownershipHandovers.fromUserId, removed.userId), eq(ownershipHandovers.toUserId, removed.userId)))).run();
    }
    return removed;
  });'''+s[end:]; p.write_text(s)
p=Path('src/server/services/member-service.ts'); s=p.read_text().replace('import * as handoverRepo from \"@/server/repositories/ownership-handover-repository\";\\n','').replace('  handoverRepo.cancelForMember(input.orgId, member.userId);\\n',''); p.write_text(s)
p=Path('src/server/repositories/ownership-handover-repository.ts'); s=p.read_text().replace('and, eq, lte, or','and, eq, lte'); s=s[:s.index('\\nexport function cancelForMember')]+ '\\n'; p.write_text(s)
p=Path('src/server/db/schema/organizations.ts'); s=p.read_text().replace('import { index,', 'import { sql } from \"drizzle-orm\";\\nimport { index,'); s=s.replace('  resolvedAt: text(\"resolved_at\"),\\n});','  resolvedAt: text(\"resolved_at\"),\\n}, (table) => [uniqueIndex(\"ownership_handovers_pending_idx\").on(table.orgId).where(sql"'`${table.status} = '"\\'pending\\'"'`)]);'"'); p.write_text(s)
PY
npx tsc --noEmit"

